/* From Uiverse.io by faxriddin20  - Tags: neumorphism, minimalist, smooth, hover effect */
.__UIV_SCOPE__ .telegram {
  transition: none 0.5s ease;
  display: flex;
  align-items: center;
  position: relative;
  padding-left: 10px;
  padding-right: 10px;
  width: 130px;
  height: 50px;
  gap: 10px;
  border: none;
  background-color: rgb(42 171 238);
  color: white;
  border-radius: 15px;
  cursor: pointer;
}

.__UIV_SCOPE__ .telegram-text {
  transition: none 0.3s ease;
  font-weight: bold;
  font-size: 1rem;
}

.__UIV_SCOPE__ .telegram:hover .telegram-text {
  display: none;
  position: absolute;
}

.__UIV_SCOPE__ .telegram-svg {
  width: 23px;
  height: 23px;
  transition: 0.8s;
}

.__UIV_SCOPE__ .telegram:hover .telegram-svg {
  margin-left: 40px;
  display: block;
  transform: rotate(50deg);
}
